import i18n from '~/shared/i18n/i18n';
import { useNavigate, usePhoneCall } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';

export const FaqBottomButtons = () => {
  const { openPhoneCall } = usePhoneCall();
  const { navigate } = useNavigate();

  const fnGoInquiry = () => {
    navigate(PATHS.community.inquiry);
  };

  const handlePhoneCall = (number: string) => () => {
    openPhoneCall(number);
  };

  return (
    <div className="faq-btm-bnn">
      <p>{i18n.t('text:unableToResolveIssue')}</p>
      <div className="faq-btm-btn">
        <button type="button" onClick={fnGoInquiry}>
          {i18n.t('oneOnOneInquirySubmit')}
        </button>
        <button type="button" onClick={handlePhoneCall('02-1111-1111')}>
          {i18n.t('phoneInquiry')}
        </button>
      </div>
    </div>
  );
};
