import { ErrorBoundary } from '@suspensive/react';
import { Fragment, Suspense, useState } from 'react';
import { FallbackErrorMessage } from '~/widgets/fallbacks/ui/fallback-error-message';
import { FullScreenLoading } from '~/widgets/loading/full-screen-loading';
import { useSetHeaderTitle, useSetIsPullToRefreshEnabled } from '~/widgets/sub-layout/use-sub-layout';
import { CommunityParams } from '~/entities/community/model/types';
import { FaqBottomButtons } from '~/entities/community/ui/faq-bottom-buttons';
import { FaqContent } from '~/entities/community/ui/faq-content';
import { FaqFilter } from '~/entities/community/ui/faq-filter';
import { CommunityTypeCode } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';

export const FaqPage = () => {
  useSetIsPullToRefreshEnabled(true);
  useSetHeaderTitle(i18n.t('frequentlyAskedQuestions'));

  const [search, setSearch] = useState<CommunityParams>({ nttTycd: CommunityTypeCode.자주묻는질문, ctgry: '' });

  return (
    <Fragment>
      <div className="content sub has-btm-btn">
        <FaqFilter search={search} setSearch={setSearch} />
        <div className="board-list" key={JSON.stringify(search)}>
          <ErrorBoundary fallback={FallbackErrorMessage}>
            <Suspense fallback={<FullScreenLoading />}>
              <FaqContent search={search} />
            </Suspense>
          </ErrorBoundary>
        </div>
      </div>
      <FaqBottomButtons />
    </Fragment>
  );
};
