import clsx from 'clsx';
import { Dispatch, SetStateAction, useEffect, useRef } from 'react';
import { useGetCodeManage } from '~/entities/comcode/api/use-comcode-api';
import { COM_CODE } from '~/entities/comcode/model/constants';
import { CommunityParams } from '~/entities/community/model/types';
import i18n from '~/shared/i18n/i18n';

type Props = {
  search: CommunityParams;
  setSearch: Dispatch<SetStateAction<CommunityParams>>;
};

export const FaqFilter = ({ search, setSearch }: Props) => {
  const refs = useRef<(HTMLButtonElement | null)[]>([]);
  const { data: codeData } = useGetCodeManage(COM_CODE.COMMUNITY_CATEGORY);

  const fnFilter = (item: string) => {
    setSearch((prev) => {
      return { ...prev, ctgry: item };
    });
  };

  useEffect(() => {
    const index = (codeData?.tbSysCodeValueList?.findIndex((item) => item.cdValue === search.ctgry) ?? -1) + 1;
    if (refs.current[index]) {
      refs.current[index]?.scrollIntoView({
        behavior: 'smooth',
        inline: 'center',
        block: 'nearest',
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [search]);

  return (
    <div className="filter">
      <button
        key={`li_0`}
        ref={(el) => (refs.current[0] = el)}
        type="button"
        className={clsx('filter-btn', { on: '' === search.ctgry })}
        onClick={() => {
          fnFilter('');
        }}
      >
        <span>{i18n.t('total')}</span>
      </button>
      {codeData?.tbSysCodeValueList?.map((item, index) => (
        <button
          key={`li_${item.cdValue}_${index}`}
          ref={(el) => {
            if (item.cdValue) {
              refs.current[index + 1] = el;
            }
          }}
          type="button"
          className={clsx('filter-btn', { on: item.cdValue === search.ctgry })}
          onClick={() => {
            fnFilter(item.cdValue ?? '');
          }}
        >
          <span>{item.cdValueNm}</span>
        </button>
      ))}
    </div>
  );
};
