import { useEffect } from 'react';
import { useInView } from 'react-intersection-observer';
import { EmptyList } from '~/widgets/empty-list';
import { resetFaqListQuery, useFaqListInfiniteQuery } from '~/entities/community/api/use-faq-list-infinite-query';
import { CommunityParams } from '~/entities/community/model/types';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';

type Props = {
  search: CommunityParams;
};
export const FaqContent = ({ search }: Props) => {
  const { navigate } = useNavigate();
  const [ref, inView] = useInView();
  const { data: list, fetchNextPage, hasNextPage } = useFaqListInfiniteQuery({ search });
  const fnGoDetail = (item: CommunityParams) => {
    navigate(`${PATHS.community.faqDetail}${item.nttManageId}`, { state: item.nttManageId });
  };

  useEffect(() => {
    if (hasNextPage && inView) fetchNextPage();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hasNextPage, inView]);

  const flattenList = list?.pages.map((page) => page?.result?.list).flat() || [];
  if (!list || flattenList.length === 0) {
    return <EmptyList message={i18n.t('validation:noPostsAvailable')} reset={resetFaqListQuery} />;
  }

  return (
    <ul>
      {flattenList?.map(
        (item, index) =>
          item && (
            <li key={`li_${item?.nttManageId}_${index}`} ref={index + 1 === flattenList.length ? ref : null}>
              <button
                type="button"
                onClick={() => {
                  fnGoDetail(item);
                }}
              >
                <span>{item.ctgryNm}</span>
                <p>{item.nttSj}</p>
              </button>
            </li>
          ),
      )}
    </ul>
  );
};
